function scrollToY(e){window.scrollTo({top:e,behavior:"smooth"})}function elemOffsetTop(e){e=e.getBoundingClientRect();return window.pageYOffset+e.top}window.addEventListener("load",function(){var e=this.document.querySelectorAll(".menu__list .menu__item a, .promo__button, .info__button");scrollToY(0),e.forEach(l=>{l.addEventListener("click",function(n){n.preventDefault();{n=l.hash;let e=document.querySelector(n),o=window.getComputedStyle(e),t=parseFloat(o.marginTop);0==t&&(t=30),null!==e&&scrollToY(elemOffsetTop(e)-t)}})})});